fn capped(m:&GalaxyModel,s:SystemId,r:f64)->usize{
 let mut seen=HashSet::from([s]);let mut todo=vec![s];
 while let Some(current)=todo.pop(){let a=m.system(current).unwrap().address;
  for (id,d) in m.nearest_systems_from_address(&a,100){if d<=r && seen.insert(id){todo.push(id);}}
 } seen.len()
}
