supplemental_public_probe.source:
use nms_core::{address::GalacticAddress, system::System};
use nms_graph::{model::GalaxyModel, spatial::SystemId, route::{Route, RouteHop, RouteError}};
fn main() {
    let mut model = GalaxyModel::new();
    let a = GalacticAddress::new(0,0,0,1,0,0);
    let b = GalacticAddress::new(0,0,0,1,0,9);
    let missing = SystemId::from_address(&GalacticAddress::new(4,0,0,409,0,9));
    for address in [a,b] { model.insert_system(System::new(address,None,None,None,vec![])); }
    let ids = [SystemId::from_address(&a), SystemId::from_address(&b), missing];
    let manual = |order: &[SystemId]| Route { hops: order.iter().map(|id| RouteHop {system_id:*id, is_waypoint:true, leg_distance_ly:12., cumulative_ly:12.}).collect(), total_distance_ly:24. };
    let mut checks = 0;
    for order in [&ids[..], &ids[2..]] {
        for result in [model.build_route_from_order(order), model.two_opt_improve(order.to_vec()), model.constrain_hops(&manual(order),400.)] {
            assert!(matches!(result, Err(RouteError::SystemNotFound(id)) if id == missing)); checks += 1;
        }
    }
    for closed in [false,true] {
        for result in [model.tsp_nearest_neighbor(ids[0],&ids[1..],closed), model.tsp_two_opt(ids[0],&ids[1..],closed)] {
            assert!(matches!(result, Err(RouteError::SystemNotFound(id)) if id == missing)); checks += 1;
        }
    }
    let route = model.shortest_path(ids[1],ids[1]).unwrap();
    assert_eq!(route.hops.len(),1);
    let hop = &route.hops[0];
    assert_eq!((hop.system_id,hop.is_waypoint,hop.leg_distance_ly,hop.cumulative_ly,route.total_distance_ly),(ids[1],false,0.,0.,0.)); checks += 1;
    let route = model.two_opt_improve(vec![ids[1]]).unwrap();
    assert_eq!(route.hops.len(),1);
    let hop = &route.hops[0];
    assert_eq!((hop.system_id,hop.is_waypoint,hop.leg_distance_ly,hop.cumulative_ly,route.total_distance_ly),(ids[1],false,0.,0.,0.)); checks += 1;
    println!("{checks}/12 public checks passed; missing payload retains galaxy9; zero routes retain false marker");
}

